            Server.js

    /*We are going to add simple authentication to our website 
We are going to collect data(email and password) entered by 
user in the HTML form, created in the INDEX.HTML file, and 
we are going to store that data in our database 
this is how we can simply register any new user */

/* if we want to log in our already registered user, 
then we collect email and password from HTML 
form created in LOGIN.HTML file, and 
we can find data(if any) associated with this 
email, and return it to user */
const mongoose = require('mongoose')
var express = require('express'); 
var app = express(); 
const bodyParser = require("body-parser"); 

// Allowing app to use body parser 
app.use(bodyParser.urlencoded({extended:true})); 

// Connecting mongoose to our database 
// named "userDatabase" 
mongoose.connect( 
'mongodb://localhost:27017/todo',{ 
useNewUrlParser: true, 
useUnifiedTopology: true
}); 

const userSchema = new mongoose.Schema({ 
email: String, 
password: String 
}); 

// Creating the User model. 
const User = new mongoose.model("User", userSchema); 


/* setting a simple get request on the home route, 
and sending our index.html file containing a form 
which will allow user to enter his details and 
register. */
app.get("/", function (req, res) { 
res.sendFile(__dirname + "/index.html"); 
}) 
app.get("/login", function(req, res) { 
res.sendFile(__dirname + "/login.html"); 
}) 

// Handling the post request on /register route. 
app.post("/register", function(req, res){ 
console.log(req.body); 

// Getting the email and password entered 
// by the user 
var email = req.body.username; 
var password = req.body.password; 

// Creating a new user with entered credentials. 
var newuser = new User({ 
	email : email, 
	password : password 
}) 

// Saving the newuser. 
newuser.save(); 
console.log("saved successfully"); 

// Sending the response that user 
// is saved successfully 
res.send("saved successfully"); 
}) 

app.post("/login", function(req, res) { 
	console.log(req.body); 

	// Getting the email and password entered 
	// by the user 
	var emailEntered = req.body.username; 
	var passwordEntered = req.body.password; 

	// Checking if the email entered exists 
	// in database or not. 
	User.findOne({email : emailEntered}, 
				function(err, data){ 
	if(data) { 

		// The email exists in the database. 
		console.log(data); 

		/* checking if the password entered 
		is matching the original password */
		if(data.password == passwordEntered){ 
			res.send("login successful!"); 
		} 
		else { 

			// Password is incorrect. 
			res.send("Incorrect Password"); 
			} 
	} 
	else { 

		// The email does not exist in the database 
		console.log(err); 
	} 
	}); 
}) 

// Allowing app to listen on port 3000 
app.listen(3000, function () { 
console.log("server started successfully"); 
})

But there are a few limitations in using this simple method of authentication.The passwords entered by the user in the registering process are left exposed to everyone in the database, i.e., anyone in the organization who has the access to the database can see any user's password. But, the passwords cannot be left exposed and we need strong encryption so that we can store our passwords safely in the database.The password is exposed to everyone who is looking into the database.Every time(maybe 20-25 times each day or even more than that) we want to use this web app or website, we have to re-enter our email and password, which becomes very time-consuming.We can not add social networking sign-in feature using this simple authentication code.Passport eliminates all of these limitations for us. If we use Passport, then: We don't have to leave our passwords exposed. The whole encryption and decryption procedure is done by Passport including the hashing and encrypting of passwords.Passport allows us to create and maintain sessions. For example, when you visit any social media website or mobile app, you do not have to log in, again and again, each time you want to use Instagram or Facebook. Rather, the information is saved, which means you don't have to log in each time you want to use the website. In technical words, a session has been created, and it will be maintained for the next few days, or a few weeks, or a few months.Passport also allows us to easily integrate authentication using Google, Facebook, LinkedIn, and various other social networking services.Step 7: For using passport, we have to install 4 npm packages, namely "passport", "passport-local", "passport-local-mongoose" and "express-session"(make sure that you download "express-session" and not "express-sessions").In the command line, write the following command to install all the four packages: npm install passport passport-local passport-local-mongoose express-sessionFollowing command will install the required packages.Once you have installed, you need to add the following code at the top of the Server.js file to include the passport module.
            Server.js

    const session = require("express-session");
const passport = require("passport");
const passportLocalMongoose = require("passport-local-mongoose");

app.use(express.static("public"));
app.use(bodyParser.urlencoded({extended:true}));

// Below all the app.use methods
app.use(session({
    secret : "any long secret key",
    resave : false,
    saveUninitialized : false
}));

Step 8: Initializing Passport and starting the Session. For initializing Passport and starting the session, write the following code just below the session declaration code.
            Server.js

    app.use(session({
  secret: "any long secret key",
  resave: false,
  saveUninitialized: false
}));

// Initializing Passport
app.use(passport.initialize());

// Starting the session
app.use(passport.session());

// Creating user schema and adding a plugin to it

const userSchema = new mongoose.Schema({
  email: String,
  password: String
});
userSchema.plugin(passportLocalMongoose);

Step 9: Now, we want that we remain logged in for some time even if we close the browser window, i.e., we want a session to be established. The session uses a Cookie to store the data and messages and allows the server to provide correct session data to the User. Process of creating Cookies and storing messages into it: Serializing Process of crumbling Cookies and extracting messages from the Cookies so that right data should be served to user: 
            Server.js

    const User = new mongoose.model("User", userSchema);
passport.use(User.createStrategy());

// Serializing and deserializing
passport.serializeUser(User.serializeUser());
passport.deserializeUser(User.deserializeUser());

Step 10: Now, we are all set to add authentication to our website. We had installed the required packages, configured the session, initialized Passport and session, and told passport to use and manage cookies.Handling the get requests:
            Server.js

    // Handling get request on the home and login route
app.get("/", function (req, res) {

  /* req.isAuthentcated() returns true or 
  false depending upon whether a session 
  is already running or not.*/
  if(req.isAuthenticated()) {

    /* if the request is already authenticated, 
